package app.fta.android;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.lang.reflect.*;
import java.util.*;
import java.util.function.BooleanSupplier;

// Dedicated-emulator fixture: actual Service, TLS and disk receipts; proxies forward encrypted bytes only.
final class BackgroundChecks {
    private final Instrumentation driver;
    BackgroundChecks(Instrumentation instrumentation){driver=instrumentation;}
    private static final String EMULATOR_HOST_ALIAS="10.0.2.2";
    private final Set<String> previousRecords=new HashSet<>();
    private int checks;private MainActivity latest;private TransferService service;private final ArrayList<ServerSocket> proxies=new ArrayList<>();
    private void check(boolean value,String label){if(!value)throw new AssertionError(label+(service==null?"":" ["+service.status()+", foreground="+service.foreground+", starting="+service.starting+", error="+service.lastError+"]"));checks++;}
    private void shell(String command)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(driver.getUiAutomation().executeShellCommand(command))){in.readAllBytes();}}
    private void await(BooleanSupplier predicate,String label,long timeout)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end){boolean[] result={false};driver.runOnMainSync(()->result[0]=predicate.getAsBoolean());if(result[0]){checks++;return;}Thread.sleep(50);}throw new AssertionError(label+(service==null?"":" ["+service.status()+", foreground="+service.foreground+", starting="+service.starting+", error="+service.lastError+"]"));}
    private TransferService current()throws Exception{Field field=TransferService.class.getDeclaredField("owner");field.setAccessible(true);return (TransferService)field.get(null);}
    private void open()throws Exception{shell("input keyevent WAKEUP");shell("wm dismiss-keyguard");shell("am start -W -n app.fta.android/.MainActivity");await(()->latest!=null&&!latest.isDestroyed()&&latest.hasWindowFocus(),"Activity visible",15000);driver.waitForIdleSync();}
    private void hide()throws Exception{shell("input keyevent HOME");shell("input keyevent SLEEP");check(!driver.getTargetContext().getSystemService(PowerManager.class).isInteractive(),"screen is actually off");}
    private TextView text(View view,String value){if(view instanceof TextView&&value.contentEquals(((TextView)view).getText()))return (TextView)view;if(view instanceof ViewGroup){for(int i=0;i<((ViewGroup)view).getChildCount();i++){TextView found=text(((ViewGroup)view).getChildAt(i),value);if(found!=null)return found;}}return null;}
    private int proxy(String address,String source)throws Exception{String host=address.substring(0,address.lastIndexOf(':'));int port=Integer.parseInt(address.substring(address.lastIndexOf(':')+1));ServerSocket listener=new ServerSocket();listener.bind(new InetSocketAddress("127.0.0.1",0));proxies.add(listener);Thread server=new Thread(()->{while(!listener.isClosed())try{Socket client=listener.accept(),remote=new Socket();remote.bind(new InetSocketAddress(source,0));remote.connect(new InetSocketAddress(host,port),5000);pump(client,remote);pump(remote,client);}catch(IOException ignored){}});server.setDaemon(true);server.start();return listener.getLocalPort();}
    private void pump(Socket source,Socket target){Thread thread=new Thread(()->{try{source.getInputStream().transferTo(target.getOutputStream());target.shutdownOutput();}catch(IOException ignored){}finally{try{source.close();}catch(IOException ignored){}try{target.close();}catch(IOException ignored){}}});thread.setDaemon(true);thread.start();}
    private JSONObject call(String method)throws Exception{return (JSONObject)NativeBridge.call(method);}
    private File file(String name,JSONObject record){JSONArray items=record.optJSONArray("items");if(items!=null)for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(name.equals(item.optString("name")))return new File(NativeBridge.received,item.optString("saved_name"));}return null;}
    private String receive(String name,long timeout)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end){JSONArray requests=(JSONArray)NativeBridge.call("registration.requests");for(int i=0;i<requests.length();i++){JSONObject r=requests.getJSONObject(i);if("FTA Mac verification".equals(r.optString("display_name"))){check(!r.has("body"),"first approval contains no body");NativeBridge.call("registration.accept",new JSONObject().put("session_id",r.getString("session_id")));}}
        JSONArray rows=(JSONArray)NativeBridge.call("inbox.list");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(previousRecords.contains(row.optString("transfer_id")))continue;if("receive".equals(row.optString("direction"))&&"completed".equals(row.optString("state"))&&file(name,row)!=null)return row.optString("peer_id");}Thread.sleep(100);}throw new AssertionError("committed incoming "+name);}
    private void stoppedSocket(String address)throws Exception{String host=address.substring(0,address.lastIndexOf(':'));int port=Integer.parseInt(address.substring(address.lastIndexOf(':')+1));long end=SystemClock.elapsedRealtime()+5000;while(SystemClock.elapsedRealtime()<end){try(Socket socket=new Socket()){socket.connect(new InetSocketAddress(host,port),300);}catch(IOException closed){checks++;return;}Thread.sleep(50);}throw new AssertionError("stopped Service still accepts sockets");}
    private void validatePattern(File file,int size)throws Exception{check(file.length()==size,"large committed size");try(InputStream in=new FileInputStream(file)){byte[] block=new byte[65536];long offset=0;int count;while((count=in.read(block))!=-1){for(int i=0;i<count;i++)if((block[i]&255)!=(offset+i)%251)throw new AssertionError("large file bytes differ");offset+=count;}}checks++;}
    private File stage(String name,boolean large)throws Exception{File folder=new File(NativeBridge.outgoing,"background-check/"+UUID.randomUUID());if(!folder.mkdirs())throw new IOException("stage mkdir");File file=new File(folder,name);try(OutputStream out=new FileOutputStream(file)){if(large){byte[] block=new byte[65536];for(int offset=0;offset<32*1024*1024;offset+=block.length){for(int i=0;i<block.length;i++)block[i]=(byte)((offset+i)%251);out.write(block);}}else out.write("actual Android JNI stream ✓".getBytes(StandardCharsets.UTF_8));}return file;}
    void run(){Bundle result=new Bundle();Application app=(Application)driver.getTargetContext().getApplicationContext();Application.ActivityLifecycleCallbacks tracker=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a instanceof MainActivity)latest=(MainActivity)a;}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(tracker);
        try{open();await(()->{try{service=current();return service!=null&&service.running&&service.foreground;}catch(Exception e){return false;}},"Service starts from visible trusted UI",15000);TransferService original=service;
            JSONArray previous=(JSONArray)NativeBridge.call("inbox.list");for(int i=0;i<previous.length();i++)previousRecords.add(previous.getJSONObject(i).optString("transfer_id"));JSONObject advert=call("host.advertisement");LanDiscovery.Lan lan=LanDiscovery.current(driver.getTargetContext());check(lan!=null,"actual LAN exists");String actual=advert.getString("address");int transferProxy=proxy(actual,lan.address),pairProxy=proxy(advert.getString("pairing_address"),lan.address);advert.put("actual_address",actual).put("address","127.0.0.1:"+transferProxy).put("pairing_address","127.0.0.1:"+pairProxy).put("background",true).put("lan_cidr",lan.cidr);
            hide();await(()->service.running&&service.foreground,"Home/screen off preserves Service",5000);
            JSONObject identity=new JSONObject(java.nio.file.Files.readString(new File(NativeBridge.state,"identity.json").toPath()));Method load=NativeBridge.class.getDeclaredMethod("loadSecret",String.class);load.setAccessible(true);byte[] key=(byte[])load.invoke(null,identity.getString("keychain_account"));check(key.length>0,"Keystore decrypts existing protected key after screen off");Arrays.fill(key,(byte)0);
            File signal=new File(driver.getTargetContext().getFilesDir(),"background-endpoints.json");java.nio.file.Files.writeString(signal.toPath(),advert.toString());String peer=receive("android-transport-check.txt",90000);
            JSONObject mac;File macFile=new File(driver.getTargetContext().getFilesDir(),"background-mac.json");mac=new JSONObject(java.nio.file.Files.readString(macFile.toPath()));mac.put("address",EMULATOR_HOST_ALIAS+":"+mac.getString("address").split(":")[1]);NativeBridge.call("host.discovered",new JSONObject().put("device",mac).put("pairing",false));
            await(()->{for(int i=0;i<service.peers.length();i++)if(peer.equals(service.peers.optJSONObject(i).optString("device_id")))return true;return false;},"real Mac route passes pinned online probe",15000);// Bring the real Activity back before the next inbound TLS file to exercise its in-app banner.
            open();File reply=stage("android-reply.txt",false);driver.runOnMainSync(()->check(service.send(peer,"",new ArrayList<>(List.of(reply)),true),"Service starts outgoing from visible UI"));await(()->!service.sending&&"completed".equals(service.lastOutcomeState),"background outgoing saved receipt",30000);
            receive("mac-background.bin",90000);
            await(()->latest.getWindow().getDecorView().findViewWithTag("receipt-banner")!=null,"real foreground receipt banner",10000);
            android.graphics.Bitmap banner=driver.getUiAutomation().takeScreenshot();try(java.io.FileOutputStream image=new java.io.FileOutputStream(new File(driver.getTargetContext().getFilesDir(),"receipt-banner-check.png"))){banner.compress(android.graphics.Bitmap.CompressFormat.PNG,100,image);}banner.recycle();
            int beforeBannerRead=new ReceiptAlerts(driver.getTargetContext()).count();driver.runOnMainSync(()->latest.getWindow().getDecorView().findViewWithTag("receipt-banner").performClick());await(()->new ReceiptAlerts(driver.getTargetContext()).count()<beforeBannerRead,"in-app banner tap opens and marks its actual receipt read",10000);driver.sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);
            JSONArray rows=(JSONArray)NativeBridge.call("inbox.list");File large=null;for(int i=0;i<rows.length();i++){if(previousRecords.contains(rows.getJSONObject(i).optString("transfer_id")))continue;File f=file("mac-background.bin",rows.getJSONObject(i));if(f!=null&&f.isFile())large=f;}check(large!=null,"background incoming final file exists");validatePattern(large,32*1024*1024);
            File outgoing=stage("android-background.bin",true);driver.getTargetContext().getSharedPreferences("fta",Context.MODE_PRIVATE).edit().putString("attachments",new JSONArray().put(outgoing.getCanonicalPath()).toString()).commit();open();MainActivity previousActivity=latest;driver.runOnMainSync(()->{check(service.send(peer,"",new ArrayList<>(List.of(outgoing)),true),"large Service send starts");check(service.activeId!=null,"transfer active before recreation");latest.recreate();});await(()->latest!=null&&latest!=previousActivity&&!latest.isDestroyed()&&service==original,"recreation retains one Service owner",10000);hide();await(()->!service.sending&&"completed".equals(service.lastOutcomeState),"large send survives recreation/Home/screen off",90000);
            boolean text=false,url=false;long end=SystemClock.elapsedRealtime()+30000;while(SystemClock.elapsedRealtime()<end&&(!text||!url)){JSONArray records=(JSONArray)NativeBridge.call("inbox.list");for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);if(!peer.equals(r.optString("peer_id"))||!"receive".equals(r.optString("direction"))||!"completed".equals(r.optString("state")))continue;JSONObject detail=(JSONObject)NativeBridge.call("inbox.get",new JSONObject().put("transfer_id",r.getString("transfer_id")));text|="Android text ✓\n둘째 줄".equals(detail.optString("body"));url|="https://example.com/fta?from=android-check".equals(detail.optString("body"));}if(!text||!url)Thread.sleep(100);}check(text&&url,"background text and URL exact final bodies");
            // Check the real background receipts, then follow an actual notification PendingIntent to mark it read.
            ReceiptAlerts alerts=new ReceiptAlerts(driver.getTargetContext());NotificationManager manager=driver.getTargetContext().getSystemService(NotificationManager.class);
            await(()->alerts.count()>=3,"durable unread receive count",10000);
            android.service.notification.StatusBarNotification received=null;
            for(android.service.notification.StatusBarNotification notice:manager.getActiveNotifications())if(notice.getTag()!=null&&notice.getNotification().getSmallIcon()!=null&&notice.getNotification().getChannelId().equals(alerts.backgroundChannel())){received=notice;break;}
            check(received!=null,"background receive uses the effective alert channel");int unread=alerts.count();open();received.getNotification().contentIntent.send();await(()->alerts.count()<unread,"notification tap opens stored receipt and clears its unread marker",10000);driver.sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);hide();
            // This emulator defers Wi-Fi auto-association while its screen is off; keep Home visible without opening FTA.
            shell("input keyevent WAKEUP");shell("wm dismiss-keyguard");shell("svc wifi disable");await(()->!service.running&&service.peers.length()==0,"Wi-Fi loss removes online state",10000);shell("svc wifi enable");await(()->service.running&&service.foreground,"trusted Wi-Fi reconnect within existing FGS grace",45000);
            String beforeStop=call("host.advertisement").getString("address");Notification status=null;for(android.service.notification.StatusBarNotification n:driver.getTargetContext().getSystemService(NotificationManager.class).getActiveNotifications())if(n.getId()==4101)status=n.getNotification();check(status!=null&&status.actions.length==2,"real ongoing notification has open/stop actions");status.actions[1].actionIntent.send();await(()->!service.foreground&&!driver.getTargetContext().getSharedPreferences("fta",Context.MODE_PRIVATE).getBoolean("receiveEnabled",true),"notification stop disables receiver",10000);stoppedSocket(beforeStop);
            open();driver.runOnMainSync(()->{text(latest.getWindow().getDecorView(),"설정").performClick();text(latest.getWindow().getDecorView(),"송수신 사용").performClick();});await(()->{try{service=current();return service.running&&service.foreground;}catch(Exception e){return false;}},"explicit UI receive switch restarts",15000);driver.runOnMainSync(()->text(latest.getWindow().getDecorView(),"송수신 사용").performClick());await(()->!service.running&&!service.foreground,"receive switch off stops sockets",10000);driver.runOnMainSync(()->text(latest.getWindow().getDecorView(),"송수신 사용").performClick());await(()->service.running&&service.foreground,"receive setting restored",15000);
            NativeBridge.call("devices.unpair",new JSONObject().put("device_id",peer));result.putString("stream","FTA background Service checks passed: "+checks+"; real TLS, 32 MiB each way, Home/screen off/recreation, Keystore, Wi-Fi and explicit stops\n");driver.finish(Activity.RESULT_OK,result);
        }catch(Throwable error){result.putString("stream","FTA background checks failed: "+error.getClass().getSimpleName()+": "+error.getMessage()+"\n");driver.finish(Activity.RESULT_CANCELED,result);}finally{app.unregisterActivityLifecycleCallbacks(tracker);for(ServerSocket socket:proxies)try{socket.close();}catch(IOException ignored){}try{shell("input keyevent WAKEUP");shell("wm dismiss-keyguard");}catch(Exception ignored){}}
    }
}
